-module(bmscl_provider_runtime).
-behaviour(gen_server).

-export([start_link/0, mode/0, managed_concurrency/2]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2, code_change/3]).

-record(state, {
    mode,
    bundle,
    aws_base = undefined,
    aws_provider = undefined,
    aws_workers = [],
    aws_target_workers = 0,
    listener = undefined
}).

start_link() ->
    gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

mode() ->
    configured_mode().

init([]) ->
    process_flag(trap_exit, true),
    Mode = configured_mode(),
    case Mode of
        native ->
            {stop, provider_runtime_started_in_native_mode};
        _ ->
            case load_bundle() of
                {error, Reason} ->
                    {stop, {provider_bundle_failed, Reason}};
                {ok, Bundle} ->
                    start_transport(Mode, Bundle)
            end
    end.

handle_call(status, _From, State) ->
    {reply, #{
        mode => State#state.mode,
        bundle => State#state.bundle,
        aws_workers => length(State#state.aws_workers),
        listener => State#state.listener
    }, State};
handle_call(_Request, _From, State) ->
    {reply, {error, unsupported_call}, State}.

handle_cast(_Msg, State) ->
    {noreply, State}.

handle_info({'EXIT', Pid, _Reason},
            State = #state{mode = Mode, aws_workers = Workers})
  when Mode =:= aws_lambda; Mode =:= aws_lambda_managed ->
    case lists:member(Pid, Workers) of
        true ->
            Remaining = lists:delete(Pid, Workers),
            erlang:send_after(250, self(), restart_aws_worker),
            {noreply, State#state{aws_workers = Remaining}};
        false ->
            {noreply, State}
    end;
handle_info(restart_aws_worker,
            State = #state{mode = Mode,
                           aws_base = Base,
                           aws_provider = Provider,
                           aws_workers = Workers,
                           aws_target_workers = Target})
  when Mode =:= aws_lambda; Mode =:= aws_lambda_managed ->
    case length(Workers) < Target of
        true ->
            Pid = spawn_link(fun() ->
                bmscl_aws_lambda_runtime:poll_loop(Base, Provider)
            end),
            {noreply, State#state{aws_workers = [Pid | Workers]}};
        false ->
            {noreply, State}
    end;
handle_info(_Msg, State) ->
    {noreply, State}.

terminate(_Reason, #state{aws_workers = Workers, listener = Listener}) ->
    lists:foreach(fun(Pid) ->
        unlink(Pid),
        exit(Pid, shutdown)
    end, Workers),
    case Listener of
        undefined -> ok;
        _ -> _ = catch cowboy:stop_listener(Listener), ok
    end,
    ok.

code_change(_OldVsn, State, _Extra) ->
    {ok, State}.

start_transport(aws_lambda, Bundle) ->
    start_aws(aws_lambda, <<"aws-lambda">>, 1, Bundle);
start_transport(aws_lambda_managed, Bundle) ->
    Concurrency = configured_aws_concurrency(),
    start_aws(aws_lambda_managed, <<"aws-lambda-managed">>, Concurrency, Bundle);
start_transport(gcp_cloud_run, Bundle) ->
    case cloud_run_port() of
        {error, Reason} -> {stop, Reason};
        {ok, Port} ->
            Dispatch = cowboy_router:compile([
                {'_', [{'_', bmscl_cloud_run_handler, #{}}]}
            ]),
            case cowboy:start_clear(
                   bmscl_cloud_run_listener,
                   [{ip, {0, 0, 0, 0}}, {port, Port}],
                   #{env => #{dispatch => Dispatch}}) of
                {ok, _Pid} ->
                    {ok, #state{
                        mode = gcp_cloud_run,
                        bundle = Bundle,
                        listener = bmscl_cloud_run_listener
                    }};
                {error, Reason} ->
                    {stop, {cloud_run_listener_failed, Reason}}
            end
    end.

start_aws(Mode, Provider, Concurrency, Bundle) ->
    case bmscl_aws_lambda_runtime:endpoint() of
        {error, Reason} ->
            {stop, Reason};
        {ok, Base} ->
            Workers = [
                spawn_link(fun() ->
                    bmscl_aws_lambda_runtime:poll_loop(Base, Provider)
                end)
                || _ <- lists:seq(1, Concurrency)
            ],
            {ok, #state{
                mode = Mode,
                bundle = Bundle,
                aws_base = Base,
                aws_provider = Provider,
                aws_workers = Workers,
                aws_target_workers = Concurrency
            }}
    end.

load_bundle() ->
    case configured_bundle_path() of
        undefined -> {error, missing_provider_bundle_path};
        Path -> bmscl_provider_bundle:load(Path)
    end.

configured_mode() ->
    Raw = case application:get_env(bmscl_supervisor, provider_mode, auto) of
        auto ->
            case os:getenv("BMSCL_PROVIDER_MODE") of
                false -> "native";
                Value -> Value
            end;
        Value -> Value
    end,
    normalize_mode(Raw).

normalize_mode(native) -> native;
normalize_mode(aws_lambda) -> aws_lambda;
normalize_mode(aws_lambda_managed) -> aws_lambda_managed;
normalize_mode(gcp_cloud_run) -> gcp_cloud_run;
normalize_mode(<<"native">>) -> native;
normalize_mode(<<"aws-lambda">>) -> aws_lambda;
normalize_mode(<<"aws-lambda-managed">>) -> aws_lambda_managed;
normalize_mode(<<"gcp-cloud-run">>) -> gcp_cloud_run;
normalize_mode("native") -> native;
normalize_mode("aws-lambda") -> aws_lambda;
normalize_mode("aws-lambda-managed") -> aws_lambda_managed;
normalize_mode("gcp-cloud-run") -> gcp_cloud_run;
normalize_mode(Other) -> error({invalid_provider_mode, Other}).

configured_bundle_path() ->
    case application:get_env(bmscl_supervisor, provider_bundle_path, undefined) of
        undefined ->
            case os:getenv("BMSCL_PROVIDER_BUNDLE") of
                false -> undefined;
                "" -> undefined;
                Value -> Value
            end;
        Value -> Value
    end.

configured_aws_concurrency() ->
    %% Managed Instances publishes the execution-environment concurrency
    %% contract through AWS_LAMBDA_MAX_CONCURRENCY. Treat that as provider
    %% authority; BeamScale may only cap it downward to bound local pollers.
    AwsMax = case os:getenv("AWS_LAMBDA_MAX_CONCURRENCY") of
        false -> error(missing_aws_lambda_max_concurrency);
        "" -> error(missing_aws_lambda_max_concurrency);
        AwsText -> parse_integer(AwsText, invalid)
    end,
    Cap0 = case application:get_env(
                  bmscl_supervisor, aws_runtime_concurrency, undefined) of
        undefined ->
            case os:getenv("BMSCL_AWS_RUNTIME_CONCURRENCY") of
                false -> 64;
                "" -> 64;
                CapText -> parse_integer(CapText, invalid)
            end;
        CapValue when is_integer(CapValue) -> CapValue;
        CapTextValue -> parse_integer(CapTextValue, invalid)
    end,
    case managed_concurrency(AwsMax, Cap0) of
        {ok, Concurrency} -> Concurrency;
        {error, Reason} -> error(Reason)
    end.

managed_concurrency(AwsMax, Cap)
  when is_integer(AwsMax), AwsMax >= 1,
       is_integer(Cap), Cap >= 1, Cap =< 64 ->
    {ok, erlang:min(AwsMax, Cap)};
managed_concurrency(AwsMax, _Cap)
  when not is_integer(AwsMax); AwsMax < 1 ->
    {error, invalid_aws_lambda_max_concurrency};
managed_concurrency(_, _) ->
    {error, invalid_aws_runtime_concurrency}.

cloud_run_port() ->
    Raw = case application:get_env(bmscl_supervisor, cloud_run_port, undefined) of
        undefined ->
            case os:getenv("PORT") of
                false -> "8080";
                "" -> "8080";
                EnvPort -> EnvPort
            end;
        ConfigPort -> ConfigPort
    end,
    Port = case Raw of
        IntegerPort when is_integer(IntegerPort) -> IntegerPort;
        TextPort -> parse_integer(TextPort, invalid)
    end,
    case Port of
        Value when is_integer(Value), Value >= 1, Value =< 65535 -> {ok, Value};
        _ -> {error, invalid_cloud_run_port}
    end.

parse_integer(Value, Fallback) when is_binary(Value) ->
    parse_integer(binary_to_list(Value), Fallback);
parse_integer(Value, Fallback) when is_list(Value) ->
    try list_to_integer(Value) of
        Int -> Int
    catch
        _:_ -> Fallback
    end;
parse_integer(_, Fallback) ->
    Fallback.

-module(bmscl_route_manifest).

-export([from_map/1, activate/1]).

-define(SCHEMA, <<"ores.routes.v1">>).

-spec activate(map()) -> {ok, updated | unchanged} | {error, term()}.
activate(Manifest) ->
    case from_map(Manifest) of
        {ok, Version, Routes} -> bmscl_route_table:replace_snapshot(Version, Routes);
        Error -> Error
    end.

-spec from_map(map()) -> {ok, non_neg_integer(), map()} | {error, term()}.
from_map(Manifest) when is_map(Manifest) ->
    case {value(schema_version, Manifest), value(routing_version, Manifest), value(routes, Manifest)} of
        {?SCHEMA, Version, Routes0}
          when is_integer(Version), Version >= 1, is_list(Routes0) ->
            compile_routes(Routes0, Version);
        {Schema, _, _} when Schema =/= ?SCHEMA ->
            {error, {unsupported_route_schema, Schema}};
        {_, Version, _} when not is_integer(Version); Version < 1 ->
            {error, invalid_routing_version};
        _ ->
            {error, invalid_route_manifest}
    end;
from_map(_) ->
    {error, invalid_route_manifest}.

compile_routes(Routes0, Version) ->
    case lists:foldl(fun compile_route/2, {ok, #{}, #{}}, Routes0) of
        {ok, Routes, _Shapes} -> {ok, Version, Routes};
        Error -> Error
    end.

compile_route(Route0, {ok, Routes, Shapes}) when is_map(Route0) ->
    Method0 = value(method, Route0),
    Path0 = value(path, Route0),
    RouteId = value(route_id, Route0),
    SourcePath = value(source_path, Route0),
    Target0 = value(target, Route0),
    case {normalize_method(Method0), normalize_path(Path0), compile_target(Target0)} of
        {{ok, Method}, {ok, Path}, {ok, Target0a}} ->
            case validate_route_pattern(Path) of
                ok ->
                    Shape = canonical_shape(Path),
                    ShapeKey = {Method, Shape},
                    Key = {Method, Path},
                    case {maps:is_key(Key, Routes), maps:find(ShapeKey, Shapes)} of
                        {true, _} -> {error, {duplicate_route, Key}};
                        {false, {ok, OtherPath}} when OtherPath =/= Path ->
                            {error, {ambiguous_route_pattern, Method, OtherPath, Path}};
                        {false, _} ->
                            Target = maybe_put(source_path, SourcePath,
                                      maybe_put(route_id, RouteId, Target0a)),
                            {ok, maps:put(Key, Target, Routes), maps:put(ShapeKey, Path, Shapes)}
                    end;
                {error, Reason} -> {error, Reason}
            end;
        {{error, Reason}, _, _} -> {error, Reason};
        {_, {error, Reason}, _} -> {error, Reason};
        {_, _, {error, Reason}} -> {error, Reason}
    end;
compile_route(_, {ok, _, _}) ->
    {error, invalid_route};
compile_route(_, Error) ->
    Error.

compile_target(Target0) when is_map(Target0) ->
    FunctionId = value(function_id, Target0),
    DeploymentId = value(deployment_id, Target0),
    Digest = value(artifact_digest, Target0),
    Runtime = value(runtime, Target0),
    case {valid_nonempty_text(FunctionId), valid_nonempty_text(DeploymentId),
          valid_digest(Digest), beam_entrypoint(Runtime)} of
        {true, true, true, {ok, Entrypoint}} ->
            case bmscl_faas_profile:normalize(Target0) of
                {ok, ProfileFields} ->
                    Base = #{
                        function_id => to_binary(FunctionId),
                        deployment_id => to_binary(DeploymentId),
                        artifact_digest => to_binary(Digest),
                        entrypoint => Entrypoint
                    },
                    {ok, maps:merge(Base, ProfileFields)};
                {error, Reason} ->
                    {error, Reason}
            end;
        {false, _, _, _} -> {error, invalid_function_id};
        {_, false, _, _} -> {error, invalid_deployment_id};
        {_, _, false, _} -> {error, invalid_artifact_digest};
        {_, _, _, {error, Reason}} -> {error, Reason}
    end;
compile_target(_) ->
    {error, invalid_route_target}.

beam_entrypoint(Runtime) when is_map(Runtime) ->
    case {value(kind, Runtime), value(entrypoint, Runtime)} of
        {beam, Entry} -> validate_entrypoint(Entry);
        {<<"beam">>, Entry} -> validate_entrypoint(Entry);
        {Kind, _} -> {error, {unsupported_beamscale_runtime, Kind}}
    end;
beam_entrypoint(_) ->
    {error, invalid_runtime_descriptor}.

validate_entrypoint(Entry0) ->
    case valid_nonempty_text(Entry0) of
        false -> {error, invalid_beam_entrypoint};
        true ->
            Entry = to_binary(Entry0),
            case re:run(Entry, <<"^[A-Za-z0-9_]+:[A-Za-z0-9_]+/[0-9]+$">>, [{capture, none}]) of
                match -> {ok, Entry};
                nomatch -> {error, invalid_beam_entrypoint}
            end
    end.

normalize_method(Method) when is_atom(Method) -> normalize_method(atom_to_binary(Method, utf8));
normalize_method(Method) when is_list(Method) -> normalize_method(unicode:characters_to_binary(Method));
normalize_method(Method) when is_binary(Method), byte_size(Method) > 0, byte_size(Method) =< 16 ->
    Upper = unicode:characters_to_binary(string:uppercase(binary_to_list(Method))),
    case lists:member(Upper, [<<"GET">>, <<"HEAD">>, <<"POST">>, <<"PUT">>, <<"PATCH">>,
                              <<"DELETE">>, <<"OPTIONS">>, <<"CONNECT">>, <<"TRACE">>, <<"ANY">>]) of
        true -> {ok, Upper};
        false -> {error, invalid_http_method}
    end;
normalize_method(_) -> {error, invalid_http_method}.

normalize_path(Path0) when is_list(Path0) -> normalize_path(unicode:characters_to_binary(Path0));
normalize_path(<<"/">> = Path) -> {ok, Path};
normalize_path(<<"/", _/binary>> = Path) when byte_size(Path) =< 4096 ->
    case valid_path_bytes(Path) andalso
         binary:match(Path, <<"?">>) =:= nomatch andalso
         binary:match(Path, <<"#">>) =:= nomatch andalso
         binary:match(Path, <<"//">>) =:= nomatch andalso
         binary:last(Path) =/= $/ of
        true -> {ok, Path};
        false -> {error, invalid_http_path}
    end;
normalize_path(_) -> {error, invalid_http_path}.

valid_path_bytes(Path) ->
    lists:all(
      fun(Byte) -> Byte >= 32 andalso Byte =/= 127 andalso Byte =/= $\\ end,
      binary_to_list(Path)).

validate_route_pattern(Path) ->
    Segments = split_path(Path),
    validate_pattern_segments(Segments, #{}, 1, length(Segments)).

validate_pattern_segments([], _Names, _Index, _Length) -> ok;
validate_pattern_segments([Segment | Rest], Names, Index, Length) ->
    case classify_pattern_segment(Segment) of
        {literal, _} ->
            validate_pattern_segments(Rest, Names, Index + 1, Length);
        {param, Name} ->
            validate_named_segment(Name, param, Rest, Names, Index, Length);
        {wildcard, Name} when Index =:= Length ->
            validate_named_segment(Name, wildcard, Rest, Names, Index, Length);
        {wildcard, _Name} ->
            {error, wildcard_must_be_terminal};
        invalid ->
            {error, invalid_route_parameter}
    end.

validate_named_segment(Name, _Kind, Rest, Names, Index, Length) ->
    case valid_parameter_name(Name) of
        false -> {error, invalid_route_parameter};
        true ->
            case maps:is_key(Name, Names) of
                true -> {error, {duplicate_route_parameter, Name}};
                false ->
                    validate_pattern_segments(Rest, maps:put(Name, true, Names), Index + 1, Length)
            end
    end.

classify_pattern_segment(<<":", Name/binary>>) when byte_size(Name) > 0 -> {param, Name};
classify_pattern_segment(<<"*", Name/binary>>) when byte_size(Name) > 0 -> {wildcard, Name};
classify_pattern_segment(<<":">>) -> invalid;
classify_pattern_segment(<<"*">>) -> invalid;
classify_pattern_segment(Segment) -> {literal, Segment}.

valid_parameter_name(Name) when byte_size(Name) =< 128 ->
    re:run(Name, <<"^[A-Za-z_][A-Za-z0-9_]*$">>, [{capture, none}]) =:= match;
valid_parameter_name(_) -> false.

canonical_shape(Path) ->
    Segments = split_path(Path),
    Canonical = [canonical_segment(S) || S <- Segments],
    <<"/", (join_segments(Canonical))/binary>>.

canonical_segment(<<":", _/binary>>) -> <<":">>;
canonical_segment(<<"*", _/binary>>) -> <<"*">>;
canonical_segment(Segment) -> Segment.

split_path(<<"/">>) -> [];
split_path(<<"/", Rest/binary>>) -> binary:split(Rest, <<"/">>, [global]).

join_segments([]) -> <<>>;
join_segments([First | Rest]) ->
    lists:foldl(fun(S, Acc) -> <<Acc/binary, "/", S/binary>> end, First, Rest).

valid_digest(Value) ->
    case maybe_binary(Value) of
        {ok, <<"sha256:", Hex/binary>>} when byte_size(Hex) =:= 64 ->
            lists:all(fun is_lower_hex/1, binary_to_list(Hex));
        _ -> false
    end.

is_lower_hex(C) when C >= $0, C =< $9 -> true;
is_lower_hex(C) when C >= $a, C =< $f -> true;
is_lower_hex(_) -> false.

valid_nonempty_text(Value) ->
    case maybe_binary(Value) of
        {ok, Bin} -> byte_size(Bin) > 0 andalso byte_size(Bin) =< 1024 andalso
                     binary:match(Bin, <<0>>) =:= nomatch;
        error -> false
    end.

maybe_binary(Value) when is_binary(Value) -> {ok, Value};
maybe_binary(Value) when is_list(Value) -> {ok, unicode:characters_to_binary(Value)};
maybe_binary(_) -> error.

to_binary(Value) when is_binary(Value) -> Value;
to_binary(Value) when is_list(Value) -> unicode:characters_to_binary(Value);
to_binary(Value) when is_atom(Value) -> atom_to_binary(Value, utf8).

maybe_put(_Key, undefined, Map) -> Map;
maybe_put(Key, Value, Map) -> Map#{Key => to_binary(Value)}.

value(Key, Map) ->
    case maps:find(Key, Map) of
        {ok, V} -> V;
        error -> maps:get(atom_to_binary(Key, utf8), Map, undefined)
    end.

-module(bmscl_route_matcher).

-export([resolve/2, match_routes/3]).

-spec resolve(term(), term()) -> {ok, map()} | {error, term()}.
resolve(Method, Path) ->
    case bmscl_route_table:resolve(Method, Path) of
        {ok, Target} -> {ok, Target#{path_params => #{}}};
        {error, route_not_found} ->
            case bmscl_route_table:snapshot() of
                {ok, _Version, Routes} -> match_routes(Method, Path, Routes);
                Error -> Error
            end;
        Error -> Error
    end.

-spec match_routes(term(), term(), map()) -> {ok, map()} | {error, term()}.
match_routes(Method0, Path0, Routes) when is_map(Routes) ->
    case {normalize_method(Method0), normalize_path(Path0)} of
        {{ok, Method}, {ok, Path}} ->
            PathSegments = split_path(Path),
            Candidates = maps:fold(
              fun({RouteMethod0, Pattern0}, Target, Acc) ->
                      case {normalize_method(RouteMethod0), normalize_path(Pattern0)} of
                          {{ok, RouteMethod}, {ok, Pattern}} ->
                              case route_method_matches(RouteMethod, Method) of
                                  true ->
                                      RawPatternSegments = split_path(Pattern),
                                      PatternSegments = classify_segments(RawPatternSegments),
                                      case match_pattern(PatternSegments, PathSegments, #{}) of
                                          {ok, Params} ->
                                              Score = specificity(RouteMethod, PatternSegments),
                                              [{Score, Pattern,
                                                Target#{path_params => Params}} | Acc];
                                          no_match -> Acc
                                      end;
                                  false -> Acc
                              end;
                          _ -> Acc
                      end;
                 (_BadKey, _Target, Acc) -> Acc
              end,
              [],
              Routes),
            choose(Candidates);
        {{error, Reason}, _} -> {error, Reason};
        {_, {error, Reason}} -> {error, Reason}
    end;
match_routes(_, _, _) ->
    {error, invalid_route_snapshot}.

%% ANY is an application-route convenience, not authority to act as an HTTP
%% tunnel/proxy endpoint. CONNECT and TRACE require an explicit method route.
%% This keeps generic dev-mode routes useful for ordinary web/API methods while
%% preventing method broadening into protocol-level or diagnostic semantics.
route_method_matches(Method, Method) -> true;
route_method_matches(<<"ANY">>, <<"GET">>) -> true;
route_method_matches(<<"ANY">>, <<"HEAD">>) -> true;
route_method_matches(<<"ANY">>, <<"POST">>) -> true;
route_method_matches(<<"ANY">>, <<"PUT">>) -> true;
route_method_matches(<<"ANY">>, <<"PATCH">>) -> true;
route_method_matches(<<"ANY">>, <<"DELETE">>) -> true;
route_method_matches(<<"ANY">>, <<"OPTIONS">>) -> true;
route_method_matches(_, _) -> false.

choose([]) -> {error, route_not_found};
choose(Candidates) ->
    [{_Score, _Pattern, Target} | _] = lists:sort(fun candidate_before/2, Candidates),
    {ok, Target}.

candidate_before({ScoreA, PatternA, _}, {ScoreB, PatternB, _}) ->
    case ScoreA =:= ScoreB of
        true -> PatternA =< PatternB;
        false -> ScoreA > ScoreB
    end.

specificity(Method, Segments) ->
    MethodScore = case Method of <<"ANY">> -> 0; _ -> 1 end,
    LiteralCount = length([ok || {literal, _} <- Segments]),
    ParamCount = length([ok || {param, _} <- Segments]),
    WildcardCount = length([ok || {wildcard, _} <- Segments]),
    {MethodScore, LiteralCount, ParamCount, -WildcardCount, length(Segments)}.

classify_segments(Segments) -> [classify_segment(S) || S <- Segments].

classify_segment(<<":", Name/binary>>) when byte_size(Name) > 0 -> {param, Name};
classify_segment(<<"*", Name/binary>>) when byte_size(Name) > 0 -> {wildcard, Name};
classify_segment(Segment) -> {literal, Segment}.

match_pattern([], [], Params) -> {ok, Params};
match_pattern([{wildcard, Name}], Rest, Params) ->
    {ok, Params#{Name => join_segments(Rest)}};
match_pattern([{literal, Segment} | RouteRest], [Segment | PathRest], Params) ->
    match_pattern(RouteRest, PathRest, Params);
match_pattern([{param, Name} | RouteRest], [Value | PathRest], Params) ->
    match_pattern(RouteRest, PathRest, Params#{Name => Value});
match_pattern(_, _, _) -> no_match.

split_path(<<"/">>) -> [];
split_path(<<"/", Rest/binary>>) -> binary:split(Rest, <<"/">>, [global]).

join_segments([]) -> <<>>;
join_segments([First | Rest]) ->
    lists:foldl(fun(S, Acc) -> <<Acc/binary, "/", S/binary>> end, First, Rest).

normalize_method(Method) when is_atom(Method) -> normalize_method(atom_to_binary(Method, utf8));
normalize_method(Method) when is_list(Method) -> normalize_method(unicode:characters_to_binary(Method));
normalize_method(Method) when is_binary(Method), byte_size(Method) > 0, byte_size(Method) =< 16 ->
    Upper = unicode:characters_to_binary(string:uppercase(binary_to_list(Method))),
    case lists:member(Upper, [<<"GET">>, <<"HEAD">>, <<"POST">>, <<"PUT">>, <<"PATCH">>,
                              <<"DELETE">>, <<"OPTIONS">>, <<"CONNECT">>, <<"TRACE">>, <<"ANY">>]) of
        true -> {ok, Upper};
        false -> {error, invalid_http_method}
    end;
normalize_method(_) -> {error, invalid_http_method}.

normalize_path(Path) when is_list(Path) -> normalize_path(unicode:characters_to_binary(Path));
normalize_path(<<"/">> = Path) -> {ok, Path};
normalize_path(<<"/", _/binary>> = Path) when byte_size(Path) =< 4096 ->
    case valid_path_bytes(Path) andalso
         binary:match(Path, <<"?">>) =:= nomatch andalso
         binary:match(Path, <<"#">>) =:= nomatch andalso
         binary:match(Path, <<"//">>) =:= nomatch andalso
         binary:last(Path) =/= $/ of
        true -> {ok, Path};
        false -> {error, invalid_http_path}
    end;
normalize_path(_) -> {error, invalid_http_path}.

valid_path_bytes(Path) ->
    lists:all(
      fun(Byte) -> Byte >= 32 andalso Byte =/= 127 andalso Byte =/= $\\ end,
      binary_to_list(Path)).
